import re
from typing import Dict, Any, List

class PostgresSecurityAnalyzer:
    """Audits SQL queries generated by AI agents for destructive commands and dangerous patterns."""

    DESTRUCTIVE_PATTERNS = [
        re.compile(r'(?i)\b(DROP\s+TABLE|DROP\s+DATABASE|DROP\s+SCHEMA)\b'),
        re.compile(r'(?i)\b(TRUNCATE\s+TABLE|TRUNCATE)\b'),
        re.compile(r'(?i)\b(ALTER\s+TABLE.*DROP)\b'),
        re.compile(r'(?i)\b(GRANT|REVOKE)\b'),
        re.compile(r'(?i)\b(DELETE\s+FROM\s+\w+\s*(;|$))\b'), # Unbounded delete
        re.compile(r'(?i)\bpg_sleep\s*\('), # Time-based blind injection probes
        re.compile(r'(?i)\bcopy\s+.*\s+to\s+program\b'), # RCE attempts
    ]

    @staticmethod
    def audit_query(sql: str) -> Dict[str, Any]:
        clean_sql = sql.strip()
        matched_threats = []

        for pattern in PostgresSecurityAnalyzer.DESTRUCTIVE_PATTERNS:
            match = pattern.search(clean_sql)
            if match:
                matched_threats.append(match.group(0))

        # Check for multiple stacked statements
        statements = [s.strip() for s in clean_sql.split(";") if s.strip()]
        has_stacked_queries = len(statements) > 1

        is_safe = (len(matched_threats) == 0) and not has_stacked_queries
        
        # Check if purely Read-Only
        is_read_only = bool(re.match(r'(?i)^\s*(SELECT|WITH|EXPLAIN)\b', clean_sql))

        return {
            "is_safe_for_agent_execution": is_safe,
            "is_read_only": is_read_only,
            "has_stacked_queries": has_stacked_queries,
            "detected_threats": matched_threats,
            "statement_count": len(statements)
        }
